committed_files.style.css:
:root { --ink:#182536; --muted:#526175; --surface:#fff; --canvas:#f3f5f8; --line:#cad2dd; --accent:#174cb4; --good:#166344; --danger:#a12424; --radius:12px; --space:8px; }
* { box-sizing:border-box; }
body { margin:0; background:var(--canvas); color:var(--ink); font:16px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
header { padding:18px max(20px,calc((100% - 1080px)/2)); background:var(--surface); border-bottom:1px solid var(--line); }
header nav { display:flex; gap:20px; flex-wrap:wrap; }
main { max-width:1080px; margin:auto; padding:24px 20px 80px; }
h1 { font-size:1.8rem; line-height:1.25; } h2 { font-size:1.2rem; }
button,input,select,textarea { font:inherit; }
button,a.button { min-height:44px; padding:9px 16px; background:var(--accent); color:white; border:1px solid transparent; border-radius:8px; cursor:pointer; }
button.secondary { color:var(--ink); background:var(--surface); border-color:var(--line); }
button:disabled { cursor:default; color:var(--muted); background:#e4e9f0; }
:focus-visible { outline:0; box-shadow:0 0 0 3px var(--accent); }
a { color:var(--accent); } input { max-width:100%; padding:10px; border:1px solid var(--line); border-radius:6px; }
.panel { background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); padding:24px; }
.muted { color:var(--muted); }.row { display:flex; gap:12px; align-items:center; flex-wrap:wrap; }
.stack { display:grid; gap:16px; }.split { display:grid; grid-template-columns:minmax(0,2fr) minmax(220px,1fr); gap:24px; }
.sr-only { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
@media(max-width:680px) { .split { grid-template-columns:minmax(0,1fr); } .panel { padding:16px; } }
@media(prefers-reduced-motion:reduce) { *,*::before,*::after { animation-duration:.01ms!important; transition-duration:.01ms!important; } }

.legacy-note { color:#b3b9c1; }
